def count_valid_distributions(n):
    # Total number of ways to distribute coins without any restrictions
    total_ways = pow(3, 3 * n, MOD)

    # Function to calculate combinations nCr % MOD
    def ncr(n, r):
        if r > n:
            return 0
        num = den = 1
        for i in range(r):
            num = num * (n - i) % MOD
            den = den * (i + 1) % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    # Calculate the number of invalid distributions
    invalid_ways = 0
    for i in range(3 * n):
        for j in range(i + 1, 3 * n):
            for k in range(j + 1, 3 * n):
                if (k - i) % 3 == 0:
                    continue
                if (j - i) % 3 == 0:
                    continue
                if (k - j) % 3 == 0:
                    continue
                if (i + n - j) % 3 == 0:
                    continue
                if (j + n - k) % 3 == 0:
                    continue
                if (k + n - i) % 3 == 0:
                    continue
                if (i + 2 * n - j) % 3 == 0:
                    continue
                if (j + 2 * n - k) % 3 == 0:
                    continue
                if (k + 2 * n - i) % 3 == 0:
                    continue
                invalid_ways += ncr(3 * n, 3) * pow(3, 3 * n - 3, MOD)
                invalid_ways %= MOD

    # Valid distributions = Total distributions - Invalid distributions
    valid_ways = (total_ways - invalid_ways + MOD) % MOD
    return valid_ways

